) VALUES (
    'franziska-preuss-profile',
    '{"en": "Franziska Preuß: Germany''s Biathlon Consistency", "de": "Franziska Preuß: Deutschlands Biathlon-Konstanz", "fr": "Franziska Preuß : La constance allemande du biathlon", "it": "Franziska Preuß: La costanza tedesca del biathlon", "es": "Franziska Preuß: La constancia alemana del biatlón", "pt": "Franziska Preuß: A consistência alemã do biatlo", "nl": "Franziska Preuß: Duitse biathlon consistentie", "ar": "فرانزيسكا برويس: ثبات البياثلون الألماني", "ja": "フランツィスカ・プロイス：ドイツバイアスロンの安定性", "zh": "Franziska Preuss: Deguo Dongji Liangxiang de Wending", "ko": "프란치스카 프로이스: 독일 바이애슬론의 일관성"}'::jsonb,
    '{"en": "The German veteran delivers reliable performances year after year. Known for smart racing and consistent shooting, she remains a threat in every competition.", "de": "Die deutsche Veteranin liefert Jahr für Jahr zuverlässige Leistungen.", "fr": "La vétérane allemande livre des performances fiables année après année.", "it": "La veterana tedesca offre prestazioni affidabili anno dopo anno.", "es": "La veterana alemana ofrece actuaciones fiables año tras año.", "pt": "A veterana alemã entrega performances confiáveis ano após ano.", "nl": "De Duitse veterane levert jaar na jaar betrouwbare prestaties.", "ar": "تقدم المخضرمة الألمانية أداءً موثوقاً عاماً بعد عام", "ja": "ドイツのベテランは毎年信頼性の高いパフォーマンスを見せています。", "zh": "Deguo laojiang meinian dou tigong kekao de biaoxian.", "ko": "독일 베테랑은 매년 안정적인 성적을 보여줍니다."}'::jsonb,
    '{"en": "<p>Franziska Preuß represents everything admirable about consistent, professional <a href=\"/biathlon-guide/\">biathlon</a> performance. The German athlete has been a fixture in World Cup racing for years, delivering podium-worthy results season after season.</p><h2>Career of Excellence</h2><p>Preuß has accumulated an impressive collection of World Cup podiums and championship medals. Her longevity at the top level of the sport speaks to her professionalism, physical conditioning, and mental strength.</p><p>While some athletes rise quickly and fade, Preuß has maintained her competitive edge through dedication to her craft.</p><h2>Technical Strengths</h2><p>Known for reliable shooting, Preuß rarely gives away positions through errors at the range. Her clean shooting allows her to focus on ski speed without the pressure of making up penalty loops.</p><p>On the ski track, she maintains solid speed throughout races, pacing herself intelligently to finish strong.</p><h2>German Biathlon Tradition</h2><p>Preuß carries forward Germany''s strong biathlon heritage. She competes against the world''s elite including <a href=\"/lisa-vittozzi-profile/\">Lisa Vittozzi</a>, <a href=\"/dorothea-wierer-profile/\">Dorothea Wierer</a>, and <a href=\"/elvira-oberg-profile/\">Elvira Öberg</a>.</p><p>Her teammate <a href=\"/katharina-schmid-profile/\">Katharina Schmid</a> competes in ski jumping, representing another strong German winter sports tradition.</p><h2>Race Intelligence</h2><p>What sets Preuß apart is her tactical awareness. She reads races well, knowing when to push and when to conserve energy. This intelligence has helped her collect medals in championships where experience matters.</p><h2>Continued Excellence</h2><p>Preuß remains motivated to add to her medal collection. Her consistent approach and professional attitude make her a role model for younger athletes in the sport.</p>", "de": "<p>Franziska Preuß repräsentiert alles Bewundernswerte an konstanter, professioneller <a href=\"/biathlon-guide/\">Biathlon</a>-Leistung. Die deutsche Athletin ist seit Jahren eine feste Größe im Weltcup.</p><h2>Karriere der Exzellenz</h2><p>Preuß hat eine beeindruckende Sammlung von Weltcup-Podestplätzen und WM-Medaillen angesammelt. Ihre Langlebigkeit auf höchstem Niveau spricht für ihre Professionalität.</p><h2>Technische Stärken</h2><p>Bekannt für zuverlässiges Schießen, gibt Preuß selten Positionen durch Fehler am Schießstand ab.</p><h2>Deutsche Biathlon-Tradition</h2><p>Preuß trägt Deutschlands starkes Biathlon-Erbe weiter. Sie kämpft gegen die Weltelite wie <a href=\"/lisa-vittozzi-profile/\">Lisa Vittozzi</a>.</p>", "fr": "<p>Franziska Preuß représente tout ce qui est admirable dans une performance de <a href=\"/biathlon-guide/\">biathlon</a> constante et professionnelle. L''athlète allemande est une référence en Coupe du monde depuis des années.</p><h2>Carrière d''excellence</h2><p>Preuß a accumulé une collection impressionnante de podiums en Coupe du monde et de médailles en championnats.</p><h2>Forces techniques</h2><p>Connue pour son tir fiable, Preuß perd rarement des positions par des erreurs au stand de tir.</p><h2>Tradition allemande</h2><p>Elle affronte l''élite mondiale comme <a href=\"/lisa-vittozzi-profile/\">Lisa Vittozzi</a>.</p>", "it": "<p>Franziska Preuß rappresenta tutto ciò che è ammirevole in una prestazione di <a href=\"/biathlon-guide/\">biathlon</a> costante e professionale. L''atleta tedesca è una presenza fissa nella Coppa del Mondo da anni.</p><h2>Carriera di eccellenza</h2><p>Preuß ha accumulato un''impressionante collezione di podi in Coppa del Mondo e medaglie ai campionati.</p><h2>Punti di forza tecnici</h2><p>Nota per il tiro affidabile, Preuß raramente cede posizioni per errori al poligono.</p>", "es": "<p>Franziska Preuß representa todo lo admirable de un rendimiento de <a href=\"/biathlon-guide/\">biatlón</a> constante y profesional. La atleta alemana ha sido una fija en la Copa del Mundo durante años.</p><h2>Carrera de excelencia</h2><p>Preuß ha acumulado una impresionante colección de podios en Copa del Mundo.</p><h2>Fortalezas técnicas</h2><p>Conocida por su tiro fiable, Preuß rara vez pierde posiciones por errores.</p>", "pt": "<p>Franziska Preuß representa tudo o que é admirável em uma performance de <a href=\"/biathlon-guide/\">biatlo</a> consistente e profissional. A atleta alemã tem sido presença constante na Copa do Mundo por anos.</p><h2>Carreira de excelência</h2><p>Preuß acumulou uma impressionante coleção de pódios na Copa do Mundo.</p>", "nl": "<p>Franziska Preuß vertegenwoordigt alles wat bewonderenswaardig is aan consistente, professionele <a href=\"/biathlon-guide/\">biathlon</a> prestaties. De Duitse atlete is al jaren een vaste waarde in de Wereldbeker.</p><h2>Carrière van excellentie</h2><p>Preuß heeft een indrukwekkende verzameling Wereldbeker podia verzameld.</p>", "ar": "<p>تمثل فرانزيسكا برويس كل ما هو جدير بالإعجاب في أداء <a href=\"/biathlon-guide/\">البياثلون</a> المتسق والمحترف. الرياضية الألمانية ثابتة في سباقات كأس العالم منذ سنوات.</p><h2>مسيرة التميز</h2><p>جمعت برويس مجموعة مثيرة للإعجاب من منصات التتويج في كأس العالم.</p>", "ja": "<p>フランツィスカ・プロイスは、一貫したプロフェッショナルな<a href=\"/biathlon-guide/\">バイアスロン</a>パフォーマンスの素晴らしさを体現しています。ドイツの選手は何年もワールドカップレースの常連です。</p><h2>卓越したキャリア</h2><p>プロイスはワールドカップ表彰台と選手権メダルの印象的なコレクションを蓄積しています。</p>", "zh": "<p>Franziska Preuss daibiao le yiguan, zhuanye de <a href=\"/biathlon-guide/\">dongji liangxiang</a> biaoxian zhong suoyou zhide zanshang de dongxi. Deguo yundongyuan duo nian lai yizhi shi Shijie Bei bisai de guding renwu.</p><h2>Zhuoyue de zhiye shengya</h2><p>Preuss jilei le lingqie yinxiang de Shijie Bei lingjiangtai he jinbiaosai jiangpai.</p>", "ko": "<p>프란치스카 프로이스는 일관되고 프로페셔널한 <a href=\"/biathlon-guide/\">바이애슬론</a> 퍼포먼스의 모든 훌륭한 점을 대표합니다. 독일 선수는 수년간 월드컵 레이싱의 고정 멤버였습니다.</p><h2>탁월한 경력</h2><p>프로이스는 월드컵 포디움과 챔피언십 메달의 인상적인 컬렉션을 축적했습니다.</p>"}'::jsonb,
